{
  "query": "ACSM warning signs stop exercise chest pain fainting severe dizziness breathlessness palpitations seek medical care",
  "passages": [
    {
      "id": "acsm-2015-warning-signs#1",
      "document": "ACSM exercise preparticipation health screening and warning signs",
      "section": "Warning signs and symptoms",
      "text": "Exercise-related cardiovascular events are often preceded by warning signs or symptoms. Signs and symptoms suggestive of cardiovascular, metabolic or renal disease include pain or discomfort in the chest, neck, jaw or arms; shortness of breath at rest or with mild exertion; dizziness or fainting; ankle swelling; palpitations or a rapid heartbeat; leg pain on walking that eases with rest; a known heart murmur; and unusual fatigue or shortness of breath with usual activities.",
      "publisher": "American College of Sports Medicine",
      "citation": "Riebe D et al. Updating ACSM's Recommendations for Exercise Preparticipation Health Screening. Med Sci Sports Exerc 2015;47(11):2473-2479. PMID 26473759",
      "url": "https://pubmed.ncbi.nlm.nih.gov/26473759/",
      "score": 17.26,
      "card_id": "8ccd81d5-e41"
    },
    {
      "id": "acsm-2015-warning-signs#2",
      "document": "ACSM exercise preparticipation health screening and warning signs",
      "section": "What to do when symptoms appear",
      "text": "Under the screening algorithm, a person who develops signs or symptoms suggestive of cardiovascular, metabolic or renal disease should stop exercising and seek medical clearance before resuming, whatever their current activity level.",
      "publisher": "American College of Sports Medicine",
      "citation": "Riebe D et al. Updating ACSM's Recommendations for Exercise Preparticipation Health Screening. Med Sci Sports Exerc 2015;47(11):2473-2479. PMID 26473759",
      "url": "https://pubmed.ncbi.nlm.nih.gov/26473759/",
      "score": 11.09,
      "card_id": "8ccd81d5-e42"
    }
  ],
